def seed_workspace_catalog(apps, schema_editor):
    OnlineWorkspace = apps.get_model("online", "OnlineWorkspace")
    OnlineWorkspaceContentItem = apps.get_model("online", "OnlineWorkspaceContentItem")

    if OnlineWorkspace.objects.exists():
        return

    for index, seed in enumerate(GROUP_WORKSPACE_SEEDS, start=1):
        workspace = OnlineWorkspace.objects.create(
            slug=seed["slug"],
            title=seed["title"],
            subtitle=seed["subtitle"],
            summary=f"Join the {seed['title']} group courses",
            icon_key=seed["icon_key"],
            kind="group",
            sort_order=index * 10,
            show_on_homepage=True,
            is_published=True,
        )
        for item in _build_group_items(seed["title"]):
            OnlineWorkspaceContentItem.objects.create(workspace=workspace, **item)

    shared_workspace = OnlineWorkspace.objects.create(
        slug="academy-resources",
        title="Academy resources",
        subtitle="Shared access",
        summary="Open the common academy library available across all sections.",
        icon_key="academy",
        kind="shared",
        sort_order=100,
        show_on_homepage=True,
        is_published=True,
    )
    for item in _build_shared_library_items():
        OnlineWorkspaceContentItem.objects.create(workspace=shared_workspace, **item)


def remove_workspace_catalog(apps, schema_editor):
    OnlineWorkspace = apps.get_model("online", "OnlineWorkspace")
    OnlineWorkspace.objects.filter(
        slug__in=[seed["slug"] for seed in GROUP_WORKSPACE_SEEDS] + ["academy-resources"]
    ).delete()


